import{bF as e}from"./booking-Bzfo1_tO.js";const a={hero:{eyebrow:"Limited-Time Offers"},smallPrint:"Limited-time offers. Terms apply; your salon confirms the final details before starting.",faqs:[{q:"How long are these offers valid?",a:"They are limited-time offers. An end date has not been announced, so your salon confirms it when you claim. Tuesday Happy Hours runs every Tuesday."},{q:"Which salons have these offers?",a:"All three Xing salons in Bangalore: Sarjapur Road, HSR Layout and Brookfield. Your salon confirms the offer when you message it."},{q:"Is the keratin offer the same for long hair?",a:"Yes. The Hair Keratin offer is one flat price for any hair length: short, medium or long."},{q:"Can I combine two offers?",a:"No. One offer applies per bill, unless your salon tells you otherwise."},{q:"Is there a minimum bill for Tuesday Happy Hours?",a:"Yes. Minimum billing applies to the Tuesday 25% off. Your salon confirms the amount when you book."},{q:"Can I walk in to claim an offer?",a:`Walk-ins are welcome at all three salons. ${e} For longer services such as keratin or colour, message first so a stylist is free.`},{q:"Do I pay anything online?",a:"No. Nothing is charged online. You pay at the salon, and the price is confirmed before we start."}]};export{a as o};
